export class Materia {
  codigo;
  nombre;
  cargaHoraria;
  correlativas;
  anio;
  estado;
  constructor(codigo, nombre, cargaHoraria, correlativas = [], anio = 0, estado = 'disponible') {
    this.codigo = codigo;
    this.nombre = nombre;
    this.cargaHoraria = cargaHoraria;
    this.correlativas = correlativas;
    this.anio = anio;
    this.estado = estado;
  }
  getCodigo() {
    return this.codigo;
  }
  getNombre() {
    return this.nombre;
  }
  getCargaHoraria() {
    return this.cargaHoraria;
  }
  getAnio() {
    return this.anio;
  }
  getEstado() {
    return this.estado;
  }
  getCorrelativas() {
    return this.correlativas;
  }
  estaDisponible(aprobadas) {
    const codigosAprobados = aprobadas.map(m => m.getCodigo());
    return this.correlativas.every(c => codigosAprobados.includes(c.getCodigo()));
  }
}
